{"args":["api","graphql","--input","-"],"stdin":"{\"query\":\"query IntakeOwner($owner: String!, $name: String!) {\\n  repository(owner: $owner, name: $name) { owner { __typename login } }\\n}\",\"variables\":{\"owner\":\"alice\",\"name\":\"proj\"}}"}
{"args":["api","graphql","--input","-"],"stdin":"{\"query\":\"query IntakeLabelled($owner: String!, $name: String!, $label: String!, $after: String) {\\n  repository(owner: $owner, name: $name) {\\n    issues(first: 100, after: $after, states: OPEN, labels: [$label]) {\\n      nodes { number }\\n      pageInfo { hasNextPage endCursor }\\n    }\\n  }\\n}\",\"variables\":{\"owner\":\"alice\",\"name\":\"proj\",\"label\":\"ready-for-agent\",\"after\":null}}"}
