{"args":["api","graphql","--input","-"],"stdin":"{\"query\":\"query IntakeMeta($owner: String!, $name: String!, $number: Int!) {\\n  repository(owner: $owner, name: $name) {\\n    issue(number: $number) {\\n      state\\n      lastEditedAt\\n      labels(first: 100) { nodes { name } }\\n      timelineItems(last: 100, itemTypes: [LABELED_EVENT, RENAMED_TITLE_EVENT]) {\\n        nodes {\\n          __typename\\n          ... on LabeledEvent { createdAt actor { login } label { name } }\\n          ... on RenamedTitleEvent { createdAt }\\n        }\\n      }\\n      comments(last: 100) { nodes { id author { login } createdAt lastEditedAt } }\\n    }\\n  }\\n}\",\"variables\":{\"owner\":\"alice\",\"name\":\"proj\",\"number\":1}}"}
